urlset:
{%- for sitemap_entry in entries %}
{%- set p = sitemap_entry.permalink %}
{%- if p is not containing(pat="/search/")
   and p is not containing(pat="/page/")
   and p is not ending_with(pat="/blog/tags/")
   and p is not containing(pat="/blog/authors/") %}

  {{ p | escape_xml | safe }}
  {%- if sitemap_entry.updated %}{{ sitemap_entry.updated }}{% endif %}

{%- endif %}
{%- endfor %}
